solution.javascript:
var MinStack = function() {
  this.stack = [];
  this.minStack = [];
};
MinStack.prototype.push = function(val) {
  this.stack.push(val);
  if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length-1]) this.minStack.push(val);
};
MinStack.prototype.pop = function() {
  const val = this.stack.pop();
  if (val === this.minStack[this.minStack.length-1]) this.minStack.pop();
};
MinStack.prototype.top = function() { return this.stack[this.stack.length-1]; };
MinStack.prototype.getMin = function() { return this.minStack[this.minStack.length-1]; };

solution.cpp:
class MinStack {
    stack<int> st;
    stack<int> minSt;
public:
    void push(int val) {
        st.push(val);
        if (minSt.empty() || val <= minSt.top()) minSt.push(val);
    }
    void pop() {
        if (st.top() == minSt.top()) minSt.pop();
        st.pop();
    }
    int top() { return st.top(); }
    int getMin() { return minSt.top(); }
};
